import sys

def solve(s):
    vPos = []
    kPos = []
    otherPos = []

    for i, ch in enumerate(s):
        if ch == 'V':
            vPos.append(i)
        elif ch == 'K':
            kPos.append(i)
        else:
            otherPos.append(i)

    INF = float('inf') / 3
    V_len = len(vPos)
    K_len = len(kPos)
    O_len = len(otherPos)

    # Initialize 4D DP array
    dp = [[[[INF for _ in range(O_len + 1)] for _ in range(K_len + 1)] for _ in range(V_len + 1)] for _ in range(2)]
    dp[0][0][0][0] = 0

    def count(index, start, positions):
        ans = 0
        for i in range(start, len(positions)):
            if positions[i] < index:
                ans += 1
        return ans

    for V in range(V_len + 1):
        for K in range(K_len + 1):
            for O in range(O_len + 1):
                for last in range(2):
                    cur = dp[last][V][K][O]
                    if cur == INF:
                        continue
                    if V < V_len:
                        new_cost = cur + count(vPos[V], K, kPos) + count(vPos[V], O, otherPos)
                        if new_cost < dp[1][V + 1][K][O]:
                            dp[1][V + 1][K][O] = new_cost
                    if K < K_len and last == 0:
                        new_cost = cur + count(kPos[K], V, vPos) + count(kPos[K], O, otherPos)
                        if new_cost < dp[0][V][K + 1][O]:
                            dp[0][V][K + 1][O] = new_cost
                    if O < O_len:
                        new_cost = cur + count(otherPos[O], V, vPos) + count(otherPos[O], K, kPos)
                        if new_cost < dp[0][V][K][O + 1]:
                            dp[0][V][K][O + 1] = new_cost

    return int(min(dp[0][V_len][K_len][O_len], dp[1][V_len][K_len][O_len]))

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    s = input_data[1]
    print(solve(s))

if __name__ == "__main__":
    main()

